pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); c.init(address(0x1), address(0x2), address(0x3)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        uint256 countBefore = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint256 countAfter = c.proposalCount();
        assertTrue(countAfter == countBefore + 1);
    }
}
